package app.boardlens.companion;
import android.app.Application;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,application=Application.class)
public class LiveSpeedTest {
 @Test public void evaluationStreamsBeforeCompletionAndReusesEngineOptions()throws Exception{
  PhoneEngine engine=new PhoneEngine();Field field=PhoneEngine.class.getDeclaredField("output");field.setAccessible(true);BlockingQueue<String> output=(BlockingQueue<String>)field.get(engine);List<String> commands=new ArrayList<>();
  Process fake=new Process(){public OutputStream getOutputStream(){return OutputStream.nullOutputStream();}public InputStream getInputStream(){return InputStream.nullInputStream();}public InputStream getErrorStream(){return InputStream.nullInputStream();}public int waitFor(){return 0;}public int exitValue(){throw new IllegalThreadStateException();}public void destroy(){}public boolean isAlive(){return true;}};
  Writer writer=new Writer(){StringBuilder text=new StringBuilder();public void write(char[] c,int a,int n){text.append(c,a,n);}public void close(){}public void flush(){for(String command:text.toString().split("\n")){commands.add(command);if(command.equals("isready"))output.offer("readyok");if(command.startsWith("go ")){output.offer("info depth 1 score cp 31 pv e2e4");output.offer("bestmove e2e4");}}text.setLength(0);}};
  for(var pair:new Object[][]{{"process",fake},{"input",new BufferedWriter(writer)}}){Field f=PhoneEngine.class.getDeclaredField((String)pair[0]);f.setAccessible(true);f.set(engine,pair[1]);}
  PhoneSettings settings=new PhoneSettings(RuntimeEnvironment.getApplication(),"speed-test");settings.p.edit().clear().putFloat("seconds",.4f).putFloat("evaluation_seconds",.08f).putInt("evaluation_depth",9).putInt("threads",2).apply();ChessPosition board=new ChessPosition("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1");boolean[] finalReturned={false},early={false};engine.search(RuntimeEnvironment.getApplication(),board,settings,true,r->{assertFalse(finalReturned[0]);assertEquals(Integer.valueOf(31),r.lines().get(0).cp());early[0]=true;});finalReturned[0]=true;assertTrue(early[0]);assertTrue(commands.contains("go movetime 80 depth 9"));engine.search(RuntimeEnvironment.getApplication(),board,settings,false,null);assertTrue(commands.contains("go movetime 400 depth 18"));assertEquals(1,Collections.frequency(commands,"setoption name Threads value 2"));assertEquals(1,Collections.frequency(commands,"setoption name Hash value 32"));settings.p.edit().putInt("threads",3).apply();engine.search(RuntimeEnvironment.getApplication(),board,settings,true,null);assertTrue(commands.contains("setoption name Threads value 3"));
 }
}
